"""Strict JSON decoding shared by the persistent registries.

The only difference from :func:`json.loads` is that number tokens whose
lexical form is a negative zero (``-0``, ``-0.0``, ``-0e2`` ...) are rejected.
``json.loads`` silently normalizes ``-0`` to the integer ``0`` and ``-0.0``
to a non-negative float, which would let two byte-different files compare
equal; the registries instead treat such literals as malformed input. The
hooks only see number tokens, so a ``-0`` appearing inside a string is never
inspected.
"""

from __future__ import annotations

import json

__all__ = ["strict_loads", "finite_loads"]


def _is_negative_zero(token: str) -> bool:
    body = token.lstrip()
    if not body.startswith("-"):
        return False
    # A signed numeric token is negative zero exactly when its value is zero;
    # -0.5 stays non-zero, while every spelling of -0 (fraction/exponent) maps
    # to zero.
    return float(body) == 0.0


def _parse_int(token: str) -> int:
    if _is_negative_zero(token):
        raise ValueError("negative-zero number literal is not allowed")
    return int(token)


def _parse_float(token: str) -> float:
    if _is_negative_zero(token):
        raise ValueError("negative-zero number literal is not allowed")
    return float(token)


def strict_loads(text: str) -> object:
    """Parse JSON, raising ValueError on negative-zero number literals."""
    return json.loads(text, parse_int=_parse_int, parse_float=_parse_float)


def _reject_constant(token: str) -> float:
    # Only NaN/Infinity/-Infinity reach the constant hook; they are not
    # finite numbers and never valid in a verified document.
    raise ValueError("non-finite number literal is not allowed")


def finite_loads(text: str) -> object:
    """Parse JSON like strict_loads, also rejecting non-finite literals."""
    return json.loads(text, parse_int=_parse_int, parse_float=_parse_float,
                      parse_constant=_reject_constant)

"""Persistent, thread-safe capacity-offer registry."""

from __future__ import annotations

import contextlib
import json
import os
import tempfile
import threading
from typing import Any

from ._jsonio import strict_loads

__all__ = ["register"]

_VERSION = 1
_OFFER_FIELDS = ("resource_id", "region", "capacity_wh",
                 "unit_cost", "carbon_intensity")
_REQUIRED_FIELDS = frozenset(_OFFER_FIELDS)
_ROOT_FIELDS = ("version", "offers", "idempotency")


class _Store:
    def __init__(self, realpath: str) -> None:
        self.realpath = realpath
        self.lock = threading.Lock()


_stores_lock = threading.Lock()
_stores: dict[str, _Store] = {}


def _get_store(path: str) -> _Store:
    realpath = os.path.realpath(path)
    with _stores_lock:
        store = _stores.get(realpath)
        if store is None:
            store = _Store(realpath)
            _stores[realpath] = store
        return store


def _is_plain_int(value: object) -> bool:
    # bool is a subclass of int and must be rejected.
    return isinstance(value, int) and not isinstance(value, bool)


def _normalize_offer(
    offer: object,
) -> tuple[str, str, int, int, int]:
    if not isinstance(offer, dict) or set(offer.keys()) != _REQUIRED_FIELDS:
        raise ValueError("offer must be an object with exactly resource_id, "
                         "region, capacity_wh, unit_cost and carbon_intensity")

    resource_id = offer["resource_id"]
    if not isinstance(resource_id, str) or not resource_id:
        raise ValueError("resource_id must be a non-empty string")

    region = offer["region"]
    if not isinstance(region, str) or not region:
        raise ValueError("region must be a non-empty string")

    capacity_wh = offer["capacity_wh"]
    if not _is_plain_int(capacity_wh) or capacity_wh <= 0:
        raise ValueError("capacity_wh must be a non-boolean positive integer")

    unit_cost = offer["unit_cost"]
    if not _is_plain_int(unit_cost) or unit_cost < 0:
        raise ValueError("unit_cost must be a non-boolean non-negative integer")

    carbon_intensity = offer["carbon_intensity"]
    if not _is_plain_int(carbon_intensity) or carbon_intensity < 0:
        raise ValueError("carbon_intensity must be a non-boolean "
                         "non-negative integer")

    return resource_id, region, capacity_wh, unit_cost, carbon_intensity


def _validate_structure(
    data: object,
) -> tuple[dict[str, dict[str, Any]], dict[str, dict[str, str]]]:
    if not isinstance(data, dict) or set(data.keys()) != set(_ROOT_FIELDS):
        raise ValueError("registry root must be an object with keys "
                         "version, offers and idempotency")

    version = data["version"]
    if not _is_plain_int(version) or version != _VERSION:
        raise ValueError("unsupported registry version")

    offers_raw = data["offers"]
    idempotency_raw = data["idempotency"]
    if not isinstance(offers_raw, dict) or not isinstance(idempotency_raw, dict):
        raise ValueError("offers and idempotency must be objects")

    offers: dict[str, dict[str, Any]] = {}
    for name, record in offers_raw.items():
        if not isinstance(name, str) or not name:
            raise ValueError("resource ids must be non-empty strings")
        if not isinstance(record, dict) or set(record.keys()) != _REQUIRED_FIELDS:
            raise ValueError("offer record has invalid fields")
        if record["resource_id"] != name:
            raise ValueError("offer record id does not match its key")
        if not isinstance(record["region"], str) or not record["region"]:
            raise ValueError("region must be a non-empty string")
        if (not _is_plain_int(record["capacity_wh"])
                or record["capacity_wh"] <= 0):
            raise ValueError("invalid capacity_wh")
        if not _is_plain_int(record["unit_cost"]) or record["unit_cost"] < 0:
            raise ValueError("invalid unit_cost")
        if (not _is_plain_int(record["carbon_intensity"])
                or record["carbon_intensity"] < 0):
            raise ValueError("invalid carbon_intensity")
        # Rebuild in canonical field order so that replays and rewrites of
        # records stored out of order still follow _OFFER_FIELDS.
        offers[name] = {field: record[field] for field in _OFFER_FIELDS}

    idempotency: dict[str, dict[str, str]] = {}
    referenced: set[str] = set()
    for key, entry in idempotency_raw.items():
        if not isinstance(key, str) or not key:
            raise ValueError("idempotency keys must be non-empty strings")
        if not isinstance(entry, dict) or set(entry.keys()) != {"resource_id"}:
            raise ValueError("idempotency entry must be a resource_id object")
        resource_id = entry["resource_id"]
        if not isinstance(resource_id, str) or not resource_id \
                or resource_id not in offers:
            raise ValueError("idempotency entry must reference a "
                             "registered offer")
        if resource_id in referenced:
            raise ValueError("offer registered under more than one "
                             "idempotency key")
        referenced.add(resource_id)
        idempotency[key] = {"resource_id": resource_id}

    return offers, idempotency


def _load(
    realpath: str,
) -> tuple[dict[str, dict[str, Any]], dict[str, dict[str, str]]]:
    try:
        with open(realpath, encoding="utf-8") as handle:
            text = handle.read()
    except FileNotFoundError:
        return {}, {}

    try:
        data = strict_loads(text)
    except ValueError as exc:
        raise ValueError(f"registry file {realpath!r} is not valid JSON") from exc
    return _validate_structure(data)


def _atomic_write(
    realpath: str,
    offers: dict[str, dict[str, Any]],
    idempotency: dict[str, dict[str, str]],
) -> None:
    payload = {
        "version": _VERSION,
        "offers": {name: offers[name] for name in sorted(offers)},
        "idempotency": {key: idempotency[key] for key in sorted(idempotency)},
    }
    text = json.dumps(payload, ensure_ascii=False, separators=(",", ":"),
                      allow_nan=False) + "\n"

    directory = os.path.dirname(realpath) or "."
    fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".offers-",
                                    suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, realpath)
    except BaseException:
        with contextlib.suppress(OSError):
            os.unlink(tmp_path)
        raise

    dir_fd = os.open(directory, os.O_RDONLY)
    try:
        os.fsync(dir_fd)
    finally:
        os.close(dir_fd)


def register(
    path: str,
    offer: dict[str, object],
    idempotency_key: str,
) -> tuple[dict[str, object], bool]:
    """Register a capacity offer idempotently as compact UTF-8 JSON.

    Returns ``(record, created)`` where ``record`` carries resource_id,
    region, capacity_wh, unit_cost (micro-units per Wh) and carbon_intensity
    (g/kWh); ``created`` is ``True`` for a new registration and ``False``
    when the idempotency key replays an identical offer.
    """
    if not isinstance(path, str):
        raise ValueError("path must be a string")
    if not isinstance(idempotency_key, str) or not idempotency_key:
        raise ValueError("idempotency_key must be a non-empty string")
    resource_id, region, capacity_wh, unit_cost, carbon_intensity = \
        _normalize_offer(offer)

    store = _get_store(path)
    with store.lock:
        offers, idempotency = _load(store.realpath)
        record: dict[str, object] = {
            "resource_id": resource_id,
            "region": region,
            "capacity_wh": capacity_wh,
            "unit_cost": unit_cost,
            "carbon_intensity": carbon_intensity,
        }

        existing_entry = idempotency.get(idempotency_key)
        if existing_entry is not None:
            existing = offers[existing_entry["resource_id"]]
            if existing != record:
                raise ValueError("idempotency key was already used with a "
                                 "different offer")
            return dict(existing), False

        if resource_id in offers:
            raise ValueError("resource_id is already registered under "
                             "another idempotency key")

        offers[resource_id] = record
        idempotency[idempotency_key] = {"resource_id": resource_id}
        _atomic_write(store.realpath, offers, idempotency)
        return dict(record), True

    if keys != sorted(keys):
        raise ValueError(f"{label} must be ordered by key code point")


def _validate_submit_structure(data: object) -> tuple[
    dict[str, dict[str, Any]], dict[str, str], dict[str, dict[str, str]]
]:
    if not isinstance(data, dict) or set(data.keys()) != set(_SUBMIT_ROOT_FIELDS):
        raise ValueError("acceptance file root must be an object with keys "
                         "version, jobs, idempotency and audit")

    version = data["version"]
    if not _is_plain_int(version) or version != _SUBMIT_VERSION:
        raise ValueError("unsupported acceptance file version")

    jobs_raw = data["jobs"]
    idempotency_raw = data["idempotency"]
    audit_raw = data["audit"]
    if not isinstance(jobs_raw, dict) \
            or not isinstance(idempotency_raw, dict) \
            or not isinstance(audit_raw, dict):
        raise ValueError("jobs, idempotency and audit must be objects")
    _check_sorted_keys(jobs_raw, "jobs")
    _check_sorted_keys(idempotency_raw, "idempotency")
    _check_sorted_keys(audit_raw, "audit")

    jobs: dict[str, dict[str, Any]] = {}
    for name, record in jobs_raw.items():
        if not isinstance(name, str) or not name:
            raise ValueError("job ids must be non-empty strings")
        if not isinstance(record, dict) \
                or set(record.keys()) != set(_SUBMIT_JOB_FIELDS):
            raise ValueError("job record has invalid fields")
        if record["job_id"] != name or not isinstance(record["job_id"], str):
            raise ValueError("job record id does not match its key")
        if not _is_plain_int(record["work"]) or record["work"] <= 0:
            raise ValueError("invalid work")
        for field in ("deadline", "max_cost", "carbon_cap"):
            if not _is_plain_int(record[field]) or record[field] < 0:
                raise ValueError(f"invalid {field}")
        regions = _validate_region_field(record["regions"], "regions")
        residency = _validate_region_field(record["residency"], "residency")
        if not set(residency).issubset(regions):
            raise ValueError("residency regions must be a subset of regions")
        if record["state"] != _STATE:
            raise ValueError("invalid job state")
        jobs[name] = {field: record[field] for field in _SUBMIT_JOB_FIELDS}

    idempotency: dict[str, str] = {}
    referenced: set[str] = set()
    for key, job_id in idempotency_raw.items():
        if not isinstance(key, str) or not key:
            raise ValueError("idempotency keys must be non-empty strings")
        if not isinstance(job_id, str) or not job_id or job_id not in jobs:
            raise ValueError("idempotency entry must reference an accepted "
                             "job")
        if job_id in referenced:
            raise ValueError("job accepted under more than one idempotency "
                             "key")
        referenced.add(job_id)
        idempotency[key] = job_id

    events: dict[str, dict[str, str]] = {}
    for key, event in audit_raw.items():
        if not isinstance(key, str) or not key:
            raise ValueError("audit keys must be non-empty strings")
        if not isinstance(event, dict) \
                or set(event.keys()) != set(_SUBMIT_EVENT_FIELDS):
            raise ValueError("submit audit event has invalid fields")
        event_key = event["key"]
        job_id = event["job_id"]
        result = event["result"]
        if event_key != key or not isinstance(event_key, str) or not event_key:
            raise ValueError("audit event key does not match its map key")
        if not isinstance(job_id, str) or not job_id or job_id not in jobs:
            raise ValueError("audit event must reference an accepted job")
        if result != _STATE:
            raise ValueError("audit event result must be queued")
        events[key] = {"key": event_key, "job_id": job_id,
                       "result": result}

    # The three sections describe one acceptance history: each
    # idempotency key binds one job and one submit event, every accepted
    # job has both, and the event and the map agree on the job.
    if set(idempotency) != set(events):
        raise ValueError("idempotency keys and audit events do not match")
    for key, job_id in idempotency.items():
        if events[key]["job_id"] != job_id:
            raise ValueError("audit event does not match its idempotency "
                             "entry")
    if set(jobs) != referenced:
        raise ValueError("every accepted job must be bound to an "
                         "idempotency key")

    return jobs, idempotency, events


def _load_submit_file(
    realpath: str,
) -> tuple[dict[str, dict[str, Any]], dict[str, str],
           dict[str, dict[str, str]], bytes | None]:
    try:
        with open(realpath, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        return {}, {}, {}, None

    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ValueError(
            f"acceptance file {realpath!r} is not valid UTF-8") from exc
    try:
        # Negative-zero and non-finite literals are format errors.
        data = finite_loads(text)
    except ValueError as exc:
        raise ValueError(
            f"acceptance file {realpath!r} is not valid JSON") from exc
    jobs, idempotency, events = _validate_submit_structure(data)
    return jobs, idempotency, events, raw

